tasks.check:
set -e
sudo vtysh -c 'show ip ospf neighbor' | grep -q Full || { echo 'r1 has no OSPF neighbor in the Full state'; exit 1; }
ip route show proto ospf | grep -q '^192.168.2.0/24' || { echo 'r1 did not learn 192.168.2.0/24 through OSPF'; exit 1; }
if ip route show proto boot | grep -q '^192.168.2.0/24'; then echo 'r1 has a hand-added route to 192.168.2.0/24: use OSPF instead'; exit 1; fi
ping -c3 -W2 192.168.1.11 >/dev/null || { echo 'r1 cannot reach h1 (192.168.1.11)'; exit 1; }
ping -c3 -W2 -I 192.168.1.1 192.168.2.11 >/dev/null || { echo 'h2 (192.168.2.11) is not reachable from the 192.168.1.0/24 LAN'; exit 1; }
echo 'OSPF adjacency Full, 192.168.2.0/24 learned via OSPF, both LANs reach each other'

set -e
ip -o -d link show type vlan | grep -q ' id 10 ' || { echo 'r1 has no VLAN 10 subinterface'; exit 1; }
ip -o -d link show type vlan | grep -q ' id 20 ' || { echo 'r1 has no VLAN 20 subinterface'; exit 1; }
[ "$(sysctl -n net.ipv4.ip_forward)" = 1 ] || { echo 'IP forwarding is off on r1'; exit 1; }
ping -c3 -W2 192.168.10.11 >/dev/null || { echo 'h1 (192.168.10.11) does not answer on VLAN 10'; exit 1; }
ping -c3 -W2 192.168.20.11 >/dev/null || { echo 'h2 (192.168.20.11) does not answer on VLAN 20'; exit 1; }
ping -c3 -W2 -I 192.168.10.1 192.168.20.11 >/dev/null || { echo 'h2 does not answer traffic from VLAN 10 (check its gateway)'; exit 1; }
ping -c3 -W2 -I 192.168.20.1 192.168.10.11 >/dev/null || { echo 'h1 does not answer traffic from VLAN 20 (check its gateway)'; exit 1; }
echo 'VLANs 10 and 20 reach their hosts through the trunk, and r1 routes between them'

set -e
a=$(ip -o -4 addr show dev enp0s8 | awk '{print $4}' | cut -d/ -f1 | head -1)
case "$a" in 192.168.50.*) ;; *) echo 'h1 has no 192.168.50.x address on its lab interface'; exit 1;; esac
ip -o -4 addr show dev enp0s8 | grep -q dynamic || { echo "h1's address $a was not assigned by DHCP"; exit 1; }
last=${a##*.}; [ "$last" -ge 100 ] && [ "$last" -le 150 ] || { echo "h1's address $a is outside 192.168.50.100-150"; exit 1; }
[ "$(dig +short @192.168.50.1 srv1.lab)" = 192.168.50.1 ] || { echo 'srv1.lab does not resolve to 192.168.50.1 through srv1'; exit 1; }
h2=$(dig +short @192.168.50.1 h2.lab)
case "$h2" in 192.168.50.*) ;; *) echo 'h2.lab does not resolve through srv1 (are DHCP clients registered in DNS?)'; exit 1;; esac
ping -c2 -W2 "$h2" >/dev/null || { echo "h2 ($h2) does not answer"; exit 1; }
echo "h1 got $a by DHCP; srv1.lab and h2.lab ($h2) resolve through srv1; h2 answers"

set -e
ip -o -4 addr show | grep -q ' 192.168.60.11/24' || { echo 'h1 does not have 192.168.60.11/24'; exit 1; }
ping -c2 -W2 203.0.113.10 >/dev/null || { echo 'h1 cannot ping 203.0.113.10 (route, forwarding or NAT on r1?)'; exit 1; }
curl -s --max-time 5 http://203.0.113.10/ | grep -q 'upstream ok' || { echo 'h1 cannot fetch http://203.0.113.10/'; exit 1; }
echo 'h1 reaches the upstream through r1 (which has no route back to the LAN, so NAT is working)'
